// Offline copy of the app: every file is cached on the first visit, and
// served from the cache from then on, refreshed in the background whenever
// the network is there (so an update shows on the next visit).

const CACHE = 'web-label-editor';

// app-files:start: generated by `npm run docs`; do not edit by hand
const FILES = [
  'index.html',
  'style.css',
  'icon.svg',
  'manifest.webmanifest',
  'src/about.js',
  'src/app.js',
  'src/calibration.js',
  'src/catalog.js',
  'src/codes/barcode.js',
  'src/codes/qr.js',
  'src/compat.js',
  'src/credits.js',
  'src/fields.js',
  'src/help.js',
  'src/icons.js',
  'src/layout.js',
  'src/library.js',
  'src/lucide.js',
  'src/others.js',
  'src/printers/brother-ptouch.js',
  'src/printers/brother-ql.js',
  'src/printers/bytes.js',
  'src/printers/dymo-labelwriter.js',
  'src/printers/generic.js',
  'src/printers/models.js',
  'src/recfile.js',
  'src/render.js',
  'src/report.js',
  'src/rolls.js',
  'src/screen.js',
  'src/transport.js',
  'src/undo.js',
  'catalog/media.rec',
  'catalog/printers.rec',
];
// app-files:end

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(['./', ...FILES])).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (event) => {
  event.waitUntil(self.clients.claim());
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET' || new URL(request.url).origin !== self.location.origin) return;
  event.respondWith(caches.open(CACHE).then(async (cache) => {
    const cached = await cache.match(request, { ignoreSearch: true });
    const fresh = fetch(request).then((response) => {
      if (response.ok) cache.put(request, response.clone());
      return response;
    });
    if (cached) {
      event.waitUntil(fresh.catch(() => {}));
      return cached;
    }
    return fresh;
  }));
});
